let saved=readStore('devops-saved',[]);
document.body.classList.toggle('dark',readStore('devops-dark',false));
const oldDashboard=dashboard;
dashboard=function(){oldDashboard();document.querySelector('.hero h1').innerHTML='From curious<br>to <em>confident.</em>';document.querySelector('.hero p').textContent='Understand the systems behind the screen. One clear explanation, one visual, one day at a time.';document.querySelector('.hero .pill').innerHTML='<span class="live-dot"></span> YOUR PERSONAL DEVOPS WORKSPACE';document.querySelector('.hero-art').outerHTML=`<div class="system-panel"><div class="terminal-bar"><span>● ● ●</span> the-big-picture.dev</div><div class="system-art"><div class="orbit"></div><div class="art-chip">&lt;/&gt;<small>SOURCE CODE</small></div><svg viewBox="0 0 240 220" role="img" aria-label="Application package connected to the cloud"><defs><linearGradient id="cubegrad"><stop stop-color="#74ead7"/><stop offset="1" stop-color="#a094ff"/></linearGradient></defs><path d="M120 24L204 72V166L120 214L36 166V72Z" fill="#192339" stroke="url(#cubegrad)" stroke-width="2"/><path d="M36 72L120 120L204 72M120 120V214M78 48L162 96" fill="none" stroke="url(#cubegrad)" stroke-width="2"/><path d="M87 141l-14 8 14 8m66-16 14 8-14 8m-23-23-20 38" fill="none" stroke="#a094ff" stroke-width="4"/></svg><div class="art-chip cloud">☁<small>THE CLOUD</small></div></div><div class="pipeline-tabs" role="tablist" aria-label="Application journey">${['Code','Build','Ship'].map((x,i)=>`<button role="tab" aria-selected="${i===0}" data-stage="${i}">0${i+1} / ${x} →</button>`).join('')}</div><p class="pipeline-caption">Write instructions that turn an idea into an application.</p></div>`;document.querySelector('.section-heading h2').textContent='Build your understanding.';document.querySelector('.section-heading>p').textContent='Start with the foundations. Connect the dots as you go.';document.querySelector('.section-heading').insertAdjacentHTML('beforeend','<div class="filters"><button class="selected" data-filter="all">All chapters</button><button data-filter="new">To explore</button><button data-filter="done">Completed</button></div>');document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));document.querySelectorAll('.chapter').forEach((el,i)=>{const done=getRead(days[i])===days[i].topics.length;el.hidden=b.dataset.filter==='done'?!done:b.dataset.filter==='new'?done:false;});document.querySelectorAll('.module-heading').forEach(h=>{let visible=false;let entry=h.nextElementSibling;while(entry&&!entry.classList.contains('module-heading')){if(entry.classList.contains('chapter')&&!entry.hidden)visible=true;entry=entry.nextElementSibling;}h.hidden=!visible;});let empty=document.querySelector('#filter-empty');if(empty)empty.remove();if(![...document.querySelectorAll('.chapter')].some(x=>!x.hidden))document.querySelector('.chapter-grid').insertAdjacentHTML('beforeend','<p id="filter-empty" class="empty">Your completed chapters will appear here as you mark lessons as read.</p>');});const captions=['Write instructions that turn an idea into an application.','Turn source code and dependencies into a tested artifact.','Deploy the artifact, run it, and check that it works.'];document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-stage]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));document.querySelector('.pipeline-caption').textContent=captions[+b.dataset.stage];});};
const oldTopicPage=topicPage;
topicPage=function(d,t){oldTopicPage(d,t);document.querySelector('.diagram-block').remove();
 const all=days.flatMap(day=>day.topics.map(topic=>({day,topic}))),position=all.findIndex(x=>key(x.day,x.topic)===key(d,t)),previous=all[position-1],next=all[position+1];
 const lessonLink=(item,direction)=>item?'<a class="lesson-nav-card '+direction+'" href="'+route(item.day,item.topic)+'"><small>'+(direction==='previous'?'← Previous lesson':'Next lesson →')+'</small><strong>'+esc(item.topic.title)+'</strong><span>Day '+String(item.day.number).padStart(2,'0')+'</span></a>':'<a class="lesson-nav-card '+direction+'" href="#"><small>'+(direction==='previous'?'← Back to':'You’ve reached the end')+'</small><strong>Learning overview</strong></a>';
 const navigation='<nav class="lesson-navigation" aria-label="Lesson navigation">'+lessonLink(previous,'previous')+lessonLink(next,'next')+'</nav>';
 document.querySelector('.reader-top').insertAdjacentHTML('afterend',navigation);
 document.querySelector('.reading-bottom').innerHTML=navigation;
 document.querySelector('.video-reference').insertAdjacentHTML('beforebegin','<section id="lesson-visual" class="visual-recap"><p class="eyebrow">CONNECT THE DOTS</p><h2>A picture to remember.</h2>'+diagramMarkup(t)+'</section>');
 document.querySelector('.lead-meta').insertAdjacentHTML('afterend','<a class="visual-jump" href="'+route(d,t)+'?section=lesson-visual">See the visual explanation ↓</a>');
 document.querySelector('.visual-jump').onclick=e=>{e.preventDefault();document.querySelector('#lesson-visual').scrollIntoView({behavior:'smooth'});};const b=document.createElement('button');b.className='small-btn';const update=()=>{b.textContent=saved.includes(key(d,t))?'★ Saved':'☆ Save';b.setAttribute('aria-pressed',String(saved.includes(key(d,t))));};update();b.onclick=()=>{const next=saved.includes(key(d,t))?saved.filter(x=>x!==key(d,t)):[...saved,key(d,t)];if(writeStore('devops-saved',next)){saved=next;update();document.querySelector('#saved-count').textContent=saved.length;}};document.querySelector('.reader-tools').prepend(b);};
const oldRender=render;
render=function(){if(location.hash==='#saved'){current=null;sidebar();const items=days.flatMap(d=>d.topics.filter(t=>saved.includes(key(d,t))).map(t=>({d,t})));main.innerHTML=`<section class="day-hero"><p class="eyebrow">YOUR PERSONAL COLLECTION</p><h1>A good idea.<br>Worth keeping.</h1><p>${items.length} saved lessons to revisit whenever you need a refresher.</p></section>${items.map(({d,t})=>`<a class="topic-row" href="${route(d,t)}"><span class="num">★</span><div><h3>${esc(t.title)}</h3><small>Day ${d.number} · ${esc(d.title)}</small></div><span class="arrow">↗</span></a>`).join('')||'<div class="empty">Select ☆ Save inside any lesson to keep it here. <a href="#">Explore chapters →</a></div>'}`;document.querySelector('.sidebar').classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false');window.scrollTo(0,0);}else oldRender();document.querySelector('#saved-count').textContent=saved.length;};
document.querySelector('#saved-nav').onclick=()=>location.hash='saved';
document.querySelector('#focus').onclick=()=>{const active=document.body.classList.toggle('focus-mode');document.querySelector('#focus').setAttribute('aria-pressed',String(active));};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA/.test(e.target.tagName)){e.preventDefault();document.querySelector('#search').focus();}});
window.addEventListener('scroll',()=>{const a=document.querySelector('.article');document.querySelector('#scroll-line').style.width=a?Math.min(100,Math.max(0,(scrollY-a.offsetTop)/Math.max(1,a.offsetHeight-innerHeight)*100))+'%':'0%';},{passive:true});
